(function(){
 'use strict';
 const C=window.QingheExamCore,KEY='qinghe-exams-v1',root=document.getElementById('exam'),esc=escapeHtml,t=(zh,en)=>ui(zh,en);
 const demo=C.validatePaper(window.QINGHE_EXAM_DEMO);
 let state={papers:[],active:null,history:[]},publishedPapers=[],filter='all',mode='practice',screen='lobby',reportId=null,saveFailed=false,storageReadFailed=false,dialogAction=null,finishing=false,lastQuestionAt=Date.now();
 const skillName=s=>({listening:t('听力','Listening'),reading:t('阅读','Reading'),writing:t('写作','Writing')})[s];
 const modeName=m=>m==='practice'?t('逐题练习','Question practice'):m==='simulation'?t('仿真考试','Exam simulation'):t('计时逐题','Timed questions');
 const scopeName=h=>h.scope==='reading'?t('阅读专项 · 非完整试卷','Reading only · not a full paper'):t('完整试卷','Full paper');
 const status=p=>p.demo?t('流程演示','Workflow demo'):p.status==='reviewed'?t('已审校','Reviewed'):t('待审校 · 仅供试做','Draft · trial only');
 function restore(raw){
  const next={...raw,papers:[],history:[],active:null};
  next.papers=(Array.isArray(raw.papers)?raw.papers:[]).map(p=>C.validatePaper(p));
  next.history=(Array.isArray(raw.history)?raw.history:[]).map(h=>({...h,paper:C.validatePaper(h.paper)}));
  if(raw.active){const a=raw.active,p=C.validatePaper(a.paper);if(typeof a.id!=='string'||!Number.isFinite(a.startedAt)||!a.answers||typeof a.answers!=='object'||(a.mode!=='practice'&&(!Number.isFinite(a.deadline)||a.deadline<=a.startedAt)))throw new Error('Invalid active exam');
   next.active={...a,paper:p,index:Math.max(0,Math.min(C.flatten(p).length-1,Number(a.index)||0)),marked:Array.isArray(a.marked)?a.marked:[],times:a.times&&typeof a.times==='object'?a.times:{},checked:a.checked&&typeof a.checked==='object'?a.checked:{}};
  }return next;
 }
 try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw)state=restore(raw)}catch(error){saveFailed=true;storageReadFailed=true}
 const allPapers=()=>[...publishedPapers.filter(p=>!state.papers.some(local=>local.id===p.id)),...state.papers,demo];
 const questions=()=>C.flatten(state.active.paper);
 const pendingCount=p=>C.flatten(p).filter(q=>q.skill==='listening'&&!q.audio&&!q.audioText).length;
 function persist(){if(storageReadFailed){saveFailed=true;return false}try{localStorage.setItem(KEY,JSON.stringify(state));saveFailed=false;return true}catch(e){saveFailed=true;return false}}
 function button(action,label,cls='secondary',extra=''){return '<button type="button" class="'+cls+'" data-exam-action="'+action+'" '+extra+'>'+label+'</button>'}
 function download(name,obj){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function openDialog(title,body,label,action){const d=document.getElementById('examDialog');d.innerHTML='<h2>'+esc(title)+'</h2>'+body+'<div class="exam-actions">'+button('dialog-confirm',esc(label),'primary')+button('dialog-cancel',t('取消','Cancel'))+'</div>';dialogAction=action;d.showModal()}
 function errorBanner(){return saveFailed?'<p class="exam-storage-error" role="alert">'+t('本机记录未能读取或保存，请先导出备份；不要清空浏览器数据。','Local records could not be read or saved. Export a backup; do not clear browser data.')+' '+button('backup',t('导出备份','Export backup'))+'</p>':''}
 function render(){if(screen==='test'&&!state.active)screen='lobby';if(screen==='report'&&!state.history.some(h=>h.id===reportId))screen='lobby';root.innerHTML=errorBanner()+(screen==='test'?testHtml():screen==='report'?reportHtml():lobbyHtml());tick()}
 function lobbyHtml(){
  const a=state.active,papers=allPapers().filter(p=>filter==='all'||p.level===filter);
  return '<div class="exam-header"><div><h1>'+t('模拟考试','Mock exams')+'</h1><p class="sub">'+t('同一份试卷，两种练习方式。','One paper, two ways to practise.')+'</p></div>'+button('history',t('考试记录','History'))+'</div>'+
   (a?'<div class="card exam-intro"><div><h2>'+t('有一份尚未提交的记录','An unfinished attempt')+'</h2><p>'+esc(a.paper.title)+' · '+modeName(a.mode)+' · '+scopeName(a)+'</p><p>'+t(a.mode==='practice'?'逐题进度已保存，可随时继续。':'离开页面后计时仍会继续。',a.mode==='practice'?'Your progress is saved.':'The timer continues while you are away.')+'</p></div>'+button('resume',t('继续作答','Resume'),'primary')+'</div>':'')+
   '<div class="exam-mode-tabs" role="group" aria-label="'+t('作答模式','Answering mode')+'">'+['practice','simulation'].map(m=>button('mode',modeName(m),'secondary'+(mode===m?' active':''),'data-mode="'+m+'" aria-pressed="'+(mode===m)+'"')).join('')+'</div><p class="exam-mode-description">'+(mode==='practice'?t('一次一道，不限时；主动核对答案后查看解析。','One question at a time, with no countdown. Check each answer to see the explanation.'):t('整卷浏览、答题卡跳转、统一计时；交卷后显示答案与报告。','Browse the paper and answer sheet under one timer. Answers appear only after submission.'))+'</p>'+
   '<div class="exam-filters" role="group" aria-label="'+t('模考等级','Exam levels')+'">'+['all',...C.levels].map(l=>button('filter',l==='all'?t('全部','All'):l,'filter-btn'+(filter===l?' active':''),'data-level="'+l+'" aria-pressed="'+(filter===l)+'"')).join('')+'</div>'+
   '<div class="exam-paper-grid">'+(papers.length?papers.map(p=>{const pending=pendingCount(p),reading=p.sections.filter(s=>s.skill==='reading').reduce((n,s)=>n+s.questions.length,0),canReading=reading&&p.readingDurationMinutes;
    return '<article class="card exam-paper"><div class="exam-meta"><span>'+esc(p.level)+'</span><span class="exam-badge">'+status(p)+'</span></div><h3>'+esc(p.title)+'</h3><p>'+C.flatten(p).length+' '+t('题','questions')+' · '+p.durationMinutes+' '+t('分钟','min')+'</p><p>'+[...new Set(p.sections.map(s=>skillName(s.skill)))].join(' / ')+'</p>'+(pending?'<p class="exam-audio-pending">'+t('听力音频待上传，完整试卷暂未开放。','Listening audio is pending; the full paper is not available yet.')+'</p>':'')+'<div class="exam-actions">'+(canReading?button('prepare',t('阅读专项 '+reading+' 题','Reading · '+reading+' questions'),'primary','data-paper="'+esc(p.id)+'" data-scope="reading"'):'')+button('prepare',t(p.demo?'体验演示卷':'完整试卷',p.demo?'Try demo':'Full paper'),canReading?'secondary':'primary','data-paper="'+esc(p.id)+'" data-scope="full" '+(pending?'disabled':''))+'</div><details class="exam-paper-outline"><summary>'+t('题型与素材状态','Sections and media')+'</summary>'+p.sections.map(s=>'<p>'+esc(s.title)+' · '+s.questions.length+' '+t('题','questions')+'</p>').join('')+'<a href="licenses/HSK1-MOCK-IMAGES.txt" target="_blank" rel="noopener">'+t('图片来源与许可','Image credits')+'</a></details></article>'}).join(''):'<p class="exam-empty">'+t('此等级暂无试卷。','No papers at this level yet.')+'</p>')+'</div>'+historyHtml()+
   '<details class="exam-import"><summary>'+t('试卷管理与导入','Manage and import papers')+'</summary><p class="exam-import-note">'+t('本机导入不会自动发布给其他用户。同编号修订不会改动正在作答的快照和历史报告。本站用于自学，前端试卷包含参考答案，不用于保密考试。','Local imports are not published. Updates do not alter ongoing attempts or past reports. This is a self-study site, not a secure examination platform.')+'</p><div class="exam-actions"><a class="secondary" href="exam-paper-template.json" download>'+t('下载模板','Template')+'</a><a class="secondary" href="exam-import-guide.md" download>'+t('导入与音频说明','Import and audio guide')+'</a>'+button('backup',t('导出考试数据','Export data'))+'</div><label>'+t('选择试卷 JSON（最多 2 MB）','Choose a paper JSON (up to 2 MB)')+'<input id="examImportFile" type="file" accept=".json,application/json"></label><p id="examImportFeedback" role="status"></p></details>';
 }
 function historyHtml(){return '<section class="exam-history card" id="examHistory"><h2>'+t('作答记录','Attempt history')+'</h2>'+(state.history.length?state.history.slice().reverse().map(h=>{const r=C.grade(h.paper,h.answers);return '<div class="exam-history-item"><div><span>'+esc(h.paper.title)+'</span><small>'+modeName(h.mode)+' · '+scopeName(h)+' · '+new Date(h.finishedAt).toLocaleString()+'</small><small>'+t('客观题','Objective')+' '+r.earned+' / '+r.objectiveMax+'</small></div>'+button('report',t('查看报告','Report'),'secondary','data-record="'+esc(h.id)+'"')+'</div>'}).join(''):'<p class="sub">'+t('完成练习后，记录会保存在此设备。','Completed attempts are saved on this device.')+'</p>')+'</section>'}
 function prepare(id,scope='full'){
  if(state.active){openDialog(t('先完成当前记录','Finish the current attempt'),'<p>'+t('请先继续或提交已有记录，再开始新的练习。','Resume or submit the existing attempt first.')+'</p>',t('继续作答','Resume'),()=>{screen='test';render()});return}
  const original=allPapers().find(p=>p.id===id);if(!original)return;let paper;try{paper=C.availablePaper(original,scope)}catch(e){toastMsg(e.message);return}
  const runMode=mode;
  openDialog(paper.title,'<p>'+modeName(runMode)+' · '+(scope==='reading'?t('阅读专项，不包含听力','Reading only; listening is excluded'):t('完整试卷','Full paper'))+'</p><p>'+C.flatten(paper).length+' '+t('题','questions')+' · '+(runMode==='practice'?t('不限时','No time limit'):paper.durationMinutes+' '+t('分钟','minutes'))+' · '+status(paper)+'</p><p>'+t(runMode==='practice'?'每题作答后可核对答案；已核对的答案锁定，记录第一次作答结果。':'开始后持续计时，刷新或离开页面不暂停；仅在交卷后展示答案。',runMode==='practice'?'Check answers one at a time. Checked responses are locked and the first response is recorded.':'The timer continues after navigation or refresh. Answers appear after submission.')+'</p>',t('开始作答','Start'),()=>start(paper,runMode,scope));
 }
 function start(paper,runMode,scope){if(state.active)return;try{C.availablePaper(paper,'full')}catch(e){toastMsg(e.message);return}const now=Date.now();state.active={id:crypto.randomUUID(),paper:JSON.parse(JSON.stringify(paper)),mode:runMode,scope,startedAt:now,deadline:runMode==='practice'?null:now+paper.durationMinutes*60000,index:0,answers:{},checked:{},marked:[],times:{}};if(!persist()){state.active=null;render();return}lastQuestionAt=now;screen='test';render();focusQuestion()}
 function spend(){const a=state.active;if(!a||screen!=='test')return;const q=questions()[a.index];a.times[q.id]=(Number(a.times[q.id])||0)+Math.max(0,(a.deadline?Math.min(Date.now(),a.deadline):Date.now())-lastQuestionAt);lastQuestionAt=Date.now()}
 function dual(zh,py,cls=''){return (py?'<div class="exam-pinyin" lang="zh-Latn">'+esc(py)+'</div>':'')+'<div class="'+cls+'">'+esc(zh)+'</div>'}
 function answerText(q,value){return q.type==='choice'?(C.answered(q,value)?String.fromCharCode(65+value)+'. '+q.options[value]:t('未作答','Unanswered')):String(value||t('未作答','Unanswered'))}
 function correctText(q){return q.type==='choice'?String.fromCharCode(65+q.answer)+'. '+q.options[q.answer]:q.type==='fill'?q.answers.join(' / '):q.sampleAnswer}
 function trendHtml(h){
  const reports=state.history.filter(x=>x.paper.id===h.paper.id&&x.paper.version===h.paper.version&&!x.paper.demo&&x.paper.status==='reviewed'&&x.mode===h.mode&&x.scope===h.scope).slice(-6);
  if(reports.length<2)return '';
  return '<h3>'+t('同卷同模式得分记录','Scores for this paper and mode')+'</h3><div class="exam-chart">'+reports.map(x=>{const r=C.grade(x.paper,x.answers);return '<span>'+new Date(x.finishedAt).toLocaleDateString()+' · '+r.earned+' / '+r.objectiveMax+'</span>'}).join('')+'</div>';
 }
 function sectionInfo(q){return '<div class="exam-section-note">'+(q.sectionInstructions?'<p>'+esc(q.sectionInstructions)+'</p>':'')+(q.sectionExample?dual(q.sectionExample,q.sectionExamplePinyin):'')+'</div>'}
 function questionHtml(q,index){
  const a=state.active,value=a.answers[q.id],locked=a.mode==='practice'&&a.checked?.[q.id],isCorrect=locked?C.grade(a.paper,a.answers).rows.find(row=>row.id===q.id)?.correct:false,labelId='exam-prompt-'+q.id;
  const choices=q.type==='choice'?'<fieldset class="exam-options'+(q.optionImages?' exam-image-options':'')+'" aria-labelledby="'+labelId+'"><legend class="sr-only">'+t('选择答案','Choose an answer')+'</legend>'+q.options.map((o,i)=>'<label class="exam-option'+(q.disabledOptions?.includes(i)?' exam-example-option':'')+'"><input type="radio" name="'+q.id+'" value="'+i+'" '+(value===i?'checked ':'')+((locked||q.disabledOptions?.includes(i))?'disabled':'')+'><span class="exam-option-content"><b>'+String.fromCharCode(65+i)+'</b>'+(q.optionImages?.[i]?'<img src="'+esc(q.optionImages[i])+'" alt="'+t('选项图片 ','Option image ')+String.fromCharCode(65+i)+'" loading="lazy">':dual(o,q.optionsPinyin?.[i]))+(q.disabledOptions?.includes(i)?'<small>'+t('示例已用','Used in example')+'</small>':'')+'</span></label>').join('')+'</fieldset>':'<label for="input-'+q.id+'">'+t('填写答案','Your answer')+'</label>'+(q.type==='writing'?'<textarea rows="6"':'<input type="text"')+' class="exam-answer" id="input-'+q.id+'" name="'+q.id+'" maxlength="12000" '+(locked?'disabled ':'')+(q.type==='writing'?'>'+esc(value||'')+'</textarea>':'value="'+esc(value||'')+'">');
  const audio=q.audio?'<audio class="exam-audio" controls preload="none" src="'+esc(q.audio)+'"></audio><p class="exam-audio-notice sub" role="status"></p>':q.audioText?button('listen',t('播放演示听力（机器语音）','Play demo (synthetic voice)'),'secondary','data-question="'+q.id+'"'):q.skill==='listening'?'<p class="sub">'+t('听力音频待上传','Listening audio pending')+'</p>':'';
  const feedback=locked?'<div class="exam-practice-feedback" role="status"><strong>'+t(isCorrect?'本题回答正确':'本题可再巩固',isCorrect?'Correct response':'Review this item')+'</strong><p>'+t('参考答案：','Reference: ')+esc(correctText(q))+'</p><p>'+esc(q.explanation)+'</p>'+(q.transcript?'<details><summary>'+t('听力原文','Listening transcript')+'</summary><p>'+esc(q.transcript)+'</p></details>':'')+'</div>':'';
  return '<article class="card exam-question" id="exam-question-'+index+'"><div class="exam-meta"><span>'+esc(q.section)+'</span><span>'+t('第 ','Question ')+(q.number||index+1)+t(' 题','')+'</span><span>'+q.points+' '+t('分','points')+'</span></div>'+(q.passage?'<div class="exam-passage">'+dual(q.passage,q.passagePinyin)+'</div>':'')+(q.promptPinyin?'<p class="exam-pinyin">'+esc(q.promptPinyin)+'</p>':'')+'<h3 id="'+labelId+'">'+esc(q.prompt)+'</h3>'+audio+choices+feedback+'<div class="exam-actions">'+(a.mode==='practice'&&!locked&&q.type!=='writing'?button('check',t('核对答案','Check answer'),'primary','data-question="'+q.id+'"'):'')+button('mark',a.marked.includes(q.id)?t('已标记','Flagged'):t('标记待检查','Flag for review'),'secondary','data-question="'+q.id+'" aria-pressed="'+a.marked.includes(q.id)+'"')+'</div></article>';
 }
 function sheetHtml(qs){const a=state.active;return '<aside class="card exam-sheet"><h3>'+t('答题卡','Answer sheet')+'</h3><div class="exam-sheet-grid">'+qs.map((q,i)=>button('jump',String(q.number||i+1),(C.answered(q,a.answers[q.id])?'answered ':'')+(i===a.index?'current ':'')+(a.marked.includes(q.id)?'marked':''),'data-index="'+i+'" aria-label="'+t('第 ','Question ')+(q.number||i+1)+'" '+(i===a.index?'aria-current="step"':''))).join('')+'</div><p id="examAnsweredCount">'+t('已答 ','Answered ')+qs.filter(q=>C.answered(q,a.answers[q.id])).length+' / '+qs.length+'</p><p>'+t('填充表示已答，圆点表示已标记。','Filled: answered. Dot: flagged.')+'</p></aside>'}
 function testHtml(){const a=state.active,qs=questions(),q=qs[a.index],simulation=a.mode==='simulation';
  const work=simulation?a.paper.sections.map(s=>{const sq=qs.filter(x=>x.section===s.title);return '<section class="exam-sim-section"><h2>'+esc(s.title)+'</h2>'+sectionInfo(sq[0])+sq.map(item=>questionHtml(item,qs.findIndex(x=>x.id===item.id))).join('')+'</section>'}).join(''):sectionInfo(q)+questionHtml(q,a.index)+'<div class="exam-question-nav">'+button('prev',t('上一题','Previous'),'secondary',a.index===0?'disabled':'')+button('next',a.index===qs.length-1?t('完成并查看报告','Finish and report'):t('下一题','Next'),'primary')+'</div>';
  return '<div class="exam-live-head"><div><h2>'+esc(a.paper.title)+'</h2><span class="exam-save-state">'+modeName(a.mode)+' · '+scopeName(a)+' · '+t('作答自动保存','Answers save automatically')+'</span></div><div><span class="exam-clock-label">'+t(a.mode==='practice'?'练习模式':'剩余时间',a.mode==='practice'?'Practice':'Time remaining')+'</span><strong class="exam-clock" id="examClock" role="timer">'+(a.mode==='practice'?t('不限时','Untimed'):'')+'</strong></div><div class="exam-actions">'+button('leave',t('保存并返回','Save and leave'))+button('submit',t('交卷','Submit'),'primary')+'</div></div>'+(simulation?'<nav class="exam-section-nav" aria-label="'+t('试卷部分','Paper sections')+'">'+a.paper.sections.map(s=>button('jump',esc(s.title),'secondary','data-index="'+qs.findIndex(q=>q.section===s.title)+'"')).join('')+'</nav>':'')+'<div class="exam-workspace'+(simulation?' exam-simulation':'')+'"><div class="exam-work-column">'+work+'</div>'+sheetHtml(qs)+'</div>';
 }
 function focusQuestion(){const a=state.active;if(!a)return;const h=root.querySelector('#exam-question-'+a.index+' h3')||root.querySelector('.exam-question h3');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}}
 function collect(){const a=state.active;if(!a||screen!=='test')return;for(const q of questions()){if(a.mode==='practice'&&a.checked?.[q.id])continue;const input=q.type==='choice'?root.querySelector('input[name="'+q.id+'"]:checked'):root.querySelector('[name="'+q.id+'"]');if(input)a.answers[q.id]=q.type==='choice'?Number(input.value):input.value}spend();persist();updateSheet()}
 function updateSheet(){const a=state.active;if(!a)return;const qs=questions();root.querySelectorAll('.exam-sheet-grid button').forEach((b,i)=>b.classList.toggle('answered',C.answered(qs[i],a.answers[qs[i].id])));const count=root.querySelector('#examAnsweredCount');if(count)count.textContent=t('已答 ','Answered ')+qs.filter(q=>C.answered(q,a.answers[q.id])).length+' / '+qs.length}
 function go(index){if(!state.active)return;collect();if(expired()){finish(true);return}state.active.index=Math.max(0,Math.min(questions().length-1,index));persist();if(state.active.mode==='simulation'){root.querySelector('#exam-question-'+state.active.index)?.scrollIntoView({block:'start',behavior:'smooth'});focusQuestion()}else{window.speechSynthesis?.cancel();render();focusQuestion();root.scrollIntoView({block:'start',behavior:'smooth'})}}
 function expired(){return !!state.active?.deadline&&Date.now()>=state.active.deadline}
 function submit(){collect();if(!state.active)return;const a=state.active,left=questions().filter(q=>!C.answered(q,a.answers[q.id])).length;openDialog(t('确认交卷','Submit attempt'),'<p>'+t('还有 '+left+' 题未作答，'+a.marked.length+' 题已标记。交卷后不能修改。','You have '+left+' unanswered and '+a.marked.length+' flagged items. Answers cannot be changed afterwards.')+'</p>',t('确认交卷','Submit'),()=>finish(false))}
 function finish(timeout){if(!state.active)return;collect();const a=state.active;if(state.history.some(h=>h.id===a.id))return;const record={...a,finishedAt:a.deadline?Math.min(Date.now(),a.deadline):Date.now(),expired:!!timeout};const prev=state.history;state.history=[...prev,record].slice(-30);state.active=null;if(!persist()){state.history=prev;state.active=a;render();return}window.speechSynthesis?.cancel();document.getElementById('examDialog').close();reportId=record.id;screen='report';render();root.scrollIntoView({block:'start'})}
 function reportHtml(){const h=state.history.find(x=>x.id===reportId),p=h.paper,result=C.grade(p,h.answers),qs=C.flatten(p),secs=Math.max(0,Math.round(Object.values(h.times||{}).reduce((n,x)=>n+(Number(x)||0),0)/1000));
  return '<div class="exam-header"><div><h1>'+t('作答报告','Attempt report')+'</h1><p class="sub">'+esc(p.title)+' · '+modeName(h.mode)+' · '+scopeName(h)+'</p></div><div class="exam-actions">'+button('lobby',t('返回模考','Back to exams'))+button('export-report',t('导出报告','Export report'))+'</div></div><article class="card"><p class="exam-badge">'+status(p)+'</p><p class="sub">'+t('练习分数不等同于官方 HSK 成绩；阅读专项不包含听力。','Practice scores are not official HSK scores. Reading-only attempts exclude listening.')+'</p><div class="exam-report-summary"><div><b>'+result.earned+' / '+result.objectiveMax+'</b><small>'+t(h.mode==='practice'?'逐题练习得分':'客观题得分',h.mode==='practice'?'Practice score':'Objective score')+'</small></div><div><b>'+Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0')+'</b><small>'+t('页面作答用时','Time answering on page')+'</small></div><div><b>'+result.wrongIds.length+'</b><small>'+t('错题及未答','Incorrect or unanswered')+'</small></div></div>'+(h.expired?'<p>'+t('已到时，系统自动交卷。','Time expired. Automatically submitted.')+'</p>':'')+(result.pendingMax?'<p>'+t('写作需人工评分，暂不计入总分。','Writing awaits human marking and is excluded from the total.')+'</p>':'')+['listening','reading','writing'].filter(s=>qs.some(q=>q.skill===s)).map(s=>{const rows=result.rows.filter(r=>r.skill===s);return '<div class="exam-skill-row"><span>'+skillName(s)+'</span><span>'+(s==='writing'?t('待人工评分','Human marking required'):rows.reduce((n,r)=>n+r.earned,0)+' / '+rows.reduce((n,r)=>n+r.points,0))+'</span></div>'}).join('')+trendHtml(h)+'<div class="exam-actions" style="margin-top:20px">'+button('add-wrong',t('将错题加入复习','Add mistakes to review'),'primary',result.wrongIds.length?'':'disabled')+'</div></article><article class="card exam-report-detail"><h2>'+t('答案与解析','Answers and explanations')+'</h2>'+qs.map((q,i)=>{const row=result.rows[i];return '<details class="exam-report-question"><summary><span class="exam-result-tag">'+t(row.pending?'待评分':row.correct?'正确':'需巩固',row.pending?'Pending':row.correct?'Correct':'Review')+'</span>'+(q.number||i+1)+'. '+esc(q.prompt)+'</summary>'+(q.passage?'<p>'+esc(q.passage)+'</p>':'')+'<p>'+t('你的答案：','Your answer: ')+esc(answerText(q,h.answers[q.id]))+'</p><p>'+t('参考答案：','Reference: ')+esc(correctText(q))+'</p>'+(q.optionImages?'<div class="exam-report-images">'+q.optionImages.map((url,i)=>url?'<figure><figcaption>'+String.fromCharCode(65+i)+'</figcaption><img src="'+esc(url)+'" alt="'+String.fromCharCode(65+i)+'" loading="lazy"></figure>':'').join('')+'</div>':'')+'<p>'+esc(q.explanation)+'</p>'+(q.transcript?'<p>'+t('听力原文：','Transcript: ')+esc(q.transcript)+'</p>':'')+(q.rubric?'<p>'+esc(q.rubric)+'</p>':'')+'</details>'}).join('')+'</article>';
 }
 function addWrong(){const h=state.history.find(x=>x.id===reportId);if(!h)return;const r=C.grade(h.paper,h.answers),qs=C.flatten(h.paper);let added=0;for(const id of r.wrongIds){const q=qs.find(x=>x.id===id),qid='exam:'+h.paper.id+':'+h.paper.version+':'+q.id;if(!learningState.reviewQueue.some(x=>x.id===qid)){learningState.reviewQueue.push({id:qid,type:'exam',value:q.prompt,examQuestion:q,dueAt:Date.now(),interval:1,ease:2.5,repetitions:0,lastGrade:null});added++}}markLearningActivity();saveLearningState();renderLearningState();toastMsg(t(added+' 道错题已加入复习，重复项已跳过。',added+' mistakes added; duplicates skipped.'))}
 async function importFile(file){if(!file)return;try{if(file.size>2*1024*1024)throw new Error('File exceeds 2 MB');const p=C.validatePaper(JSON.parse(await file.text()));if(p.id===demo.id)throw new Error('Demo ID is reserved');openDialog(t('确认导入试卷','Import paper'),'<p>'+esc(p.title)+' · '+C.flatten(p).length+' '+t('题','questions')+' · '+status(p)+'</p>',t('确认导入','Import'),()=>{const prev=state.papers;state.papers=[...prev.filter(x=>x.id!==p.id),p];if(!persist()){state.papers=prev;render();return}filter=p.level;screen='lobby';render()})}catch(e){document.getElementById('examImportFeedback').textContent=t('导入失败：','Import failed: ')+e.message}}
 function tick(){const a=state.active;if(!a||a.mode==='practice')return;const left=Math.max(0,Math.ceil((a.deadline-Date.now())/1000)),el=root.querySelector('#examClock');if(el){el.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');el.classList.toggle('urgent',left<=60)}if(left===0&&!finishing){finishing=true;try{finish(true)}finally{finishing=false}}}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-exam-action]');if(!b||b.disabled)return;const action=b.dataset.examAction;
  if(action==='mode'){mode=b.dataset.mode;render()}
  else if(action==='filter'){filter=b.dataset.level;render()}
  else if(action==='prepare')prepare(b.dataset.paper,b.dataset.scope);
  else if(action==='resume'){screen='test';lastQuestionAt=Date.now();render();focusQuestion()}
  else if(action==='leave'){collect();screen='lobby';root.querySelectorAll('audio').forEach(a=>a.pause());window.speechSynthesis?.cancel();render()}
  else if(action==='lobby'){screen='lobby';render()}
  else if(action==='history')root.querySelector('#examHistory')?.scrollIntoView({behavior:'smooth'});
  else if(action==='report'){reportId=b.dataset.record;screen='report';render()}
  else if(action==='prev')go(state.active.index-1);
  else if(action==='next'){if(state.active.index===questions().length-1)submit();else go(state.active.index+1)}
  else if(action==='jump')go(Number(b.dataset.index));
  else if(action==='mark'){collect();const a=state.active,id=b.dataset.question;a.marked=a.marked.includes(id)?a.marked.filter(x=>x!==id):[...a.marked,id];persist();b.textContent=a.marked.includes(id)?t('已标记','Flagged'):t('标记待检查','Flag for review');b.setAttribute('aria-pressed',String(a.marked.includes(id)));root.querySelectorAll('.exam-sheet-grid button').forEach((el,i)=>el.classList.toggle('marked',a.marked.includes(questions()[i].id)))}
  else if(action==='check'){collect();if(expired()){finish(true);return}const q=questions().find(q=>q.id===b.dataset.question);if(!C.answered(q,state.active.answers[q.id])){toastMsg(t('请先作答。','Please answer first.'));return}state.active.checked[q.id]=true;persist();render();focusQuestion()}
  else if(action==='submit')submit();
  else if(action==='listen'){const q=questions().find(q=>q.id===b.dataset.question);if(q?.audioText)speakText(q.audioText)}
  else if(action==='backup'){let data=state;try{data=JSON.parse(localStorage.getItem(KEY)||'null')||state}catch(e){}download('qinghe-exam-backup.json',data)}
  else if(action==='export-report'){const h=state.history.find(x=>x.id===reportId);download('qinghe-exam-report.json',{...h,grading:C.grade(h.paper,h.answers)})}
  else if(action==='add-wrong')addWrong();
 });
 root.addEventListener('input',e=>{if(e.target.matches('.exam-answer,.exam-options input')){if(expired()){finish(true);return}collect()}});
 root.addEventListener('focusin',e=>{const article=e.target.closest('.exam-question');if(article&&state.active?.mode==='simulation'){spend();state.active.index=Number(article.id.replace('exam-question-',''));persist()}});
 root.addEventListener('change',e=>{if(e.target.id==='examImportFile')importFile(e.target.files[0])});
 root.addEventListener('error',e=>{if(e.target.tagName==='AUDIO'){const note=e.target.parentElement.querySelector('.exam-audio-notice');if(note)note.textContent=t('音频暂不可用，请检查网络后重试。','Audio unavailable. Check your connection and try again.')}if(e.target.tagName==='IMG'){e.target.alt=t('图片加载失败，请刷新后重试。','Image unavailable. Refresh to retry.')}},true);
 document.getElementById('examDialog').addEventListener('click',e=>{const b=e.target.closest('[data-exam-action]');if(!b)return;const action=dialogAction;document.getElementById('examDialog').close();dialogAction=null;if(b.dataset.examAction==='dialog-confirm')action?.()});
 document.getElementById('examDialog').addEventListener('cancel',()=>{dialogAction=null});
 document.addEventListener('qinghe:languagechange',()=>{if(screen==='test')collect();render()});
 window.addEventListener('beforeunload',e=>{if(state.active){if(screen==='test')collect();e.preventDefault();e.returnValue=''}});
 document.addEventListener('visibilitychange',()=>{if(state.active){if(screen==='test')spend();persist();tick()}});
 window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{state=restore(JSON.parse(e.newValue));lastQuestionAt=Date.now();render()}catch(err){saveFailed=true;render()}});
 // Reuse the existing review scheduler and controls, adding media to the same queued question.
 const originalReviewRender=window.renderReviewItem;
 window.renderReviewItem=function(){originalReviewRender();const item=reviewItems[reviewIndex];if(!item)return;
  if(item.audioUrl){const a=document.createElement('audio');a.controls=true;a.src=item.audioUrl;a.className='exam-audio';document.getElementById('reviewMedia').replaceChildren(a)}
  const q=learningState.reviewQueue.find(x=>x.id===item.queueId)?.examQuestion;if(!q)return;
  document.querySelectorAll('#reviewOptions .choice').forEach((b,i)=>{if(q.optionImages?.[i]){const image=document.createElement('img');image.src=q.optionImages[i];image.alt=String.fromCharCode(65+i);image.className='exam-review-image';b.prepend(image)}if(q.disabledOptions?.includes(i)){b.disabled=true;b.append(' ('+t('示例已用','Example')+')')}});
 };
 async function loadPublishedPapers(){try{const response=await fetch('./exam-papers/index.json',{cache:'no-store'});if(!response.ok)throw new Error();const catalog=await response.json();if(catalog.schemaVersion!==1||!Array.isArray(catalog.papers)||catalog.papers.length>100)throw new Error();const loaded=await Promise.all(catalog.papers.map(async f=>{if(typeof f!=='string'||!/^[a-zA-Z0-9_-]+\.json$/.test(f))throw new Error();const r=await fetch('./exam-papers/'+f,{cache:'no-store'});if(!r.ok)throw new Error();return C.validatePaper(await r.json())}));if(new Set(loaded.map(p=>p.id)).size!==loaded.length||loaded.some(p=>p.id===demo.id))throw new Error();publishedPapers=loaded;if(screen==='lobby')render()}catch(e){root.insertAdjacentHTML('beforeend','<p role="status" class="sub">'+t('公开试卷暂未加载，请刷新重试；本机记录不受影响。','Published papers could not load. Refresh to retry; local records are unaffected.')+'</p>')}}
 setInterval(tick,1000);render();loadPublishedPapers();
})();
